import forgelib as F
G = F.make(slug="the-forge-heavenly-pickaxe", order=16, kw="get the heavenly pickaxe",
 title="How to Get the Heavenly Pickaxe in The Forge (Maze)",
 h1="How to Get the Heavenly (\"Heavenite\") Pickaxe in The Forge and Beat the Secret Maze",
 desc="How to get the Heavenly Pickaxe in The Forge: reach the Secret Maze, finish all 3 Maze quests for Zachariel and Zarall, then pay 2M Gold. Stats inside.",
 kw2=["the forge heavenite pickaxe","the forge heavenly pickaxe","the forge maze","how to unlock the maze the forge","the forge zachariel"],
 related=["the-forge-prismatic-pickaxe","the-forge-dragon-head-pickaxe","the-forge-pickaxe-progression","the-forge-island-3-guide"],
 ids=["N-E4D4_mxpY","FLDZaD-jPwY","FtkjCpWs6Lg"],
 lead="Fridge calls it the \"Heavenite Pickaxe\", and the game calls it the <strong>Heavenly Pickaxe</strong>. It's one of the best pickaxes on Island 3, and you get the Heavenly Pickaxe by finishing the Secret Maze. This page combines his three videos on the pickaxe and the Maze with the current steps from the Forge Wiki.",
 heading="Watch Fridge's Heavenly Pickaxe and Maze Videos",
 sections=[
 ("stats","Heavenly Pickaxe Stats","""<div class="table-wrap"><table><caption>Heavenly Pickaxe (Forge Wiki, November 11, 2026)</caption><thead><tr><th scope="col">Stat</th><th scope="col">Value</th></tr></thead><tbody>
<tr><td>Mine Power</td><td>725</td></tr><tr><td>Speed</td><td>0%</td></tr><tr><td>Luck</td><td>+85%</td></tr><tr><td>Rune slots</td><td>4</td></tr><tr><td>Rarity</td><td>Mythical</td></tr><tr><td>Cost</td><td>2,000,000 Gold (1,760,000 with the Goblin race)</td></tr></tbody></table></div>
<p>Its +85% Luck is the highest of the Frostspire pickaxes listed here. \"Heavenite\" is actually a separate Divine ore from Floating Crystals at The Peak, which is why the two names get mixed up.</p>"""),
 ("maze","How to Reach the Secret Maze","""<p>The Secret Maze came with <strong>version 1.04, The Maze Update, on January 11, 2026</strong>, the same day as Fridge's Maze Short and his second Heavenly Pickaxe video. His first video, from December 25, 2025, shows the pickaxe before the Maze existed, so the unlock has changed since.</p>
<ol class="steps"><li>On the Frostspire Expanse, take the <strong>Ferry</strong>. It carries you to the Maze entrance for a small fare.</li><li>Enter the <strong>Secret Maze</strong>, an \"ever-shifting labyrinth\" beneath the frozen island. The layout moves, so follow Fridge's route in the video rather than a fixed map.</li><li>In the heart of the maze is <strong>Fungi's Shop</strong>, which sells weapon blueprints and Fungi's Potion.</li><li>Keep going to the very end, where the angels <strong>Zachariel</strong> and <strong>Zarall</strong> wait.</li></ol>"""),
 ("quests","The Three Maze Quests","""<div class="table-wrap"><table><caption>The Secret Maze questline</caption><thead><tr><th scope="col">Quest</th><th scope="col">Kill</th><th scope="col">Reward</th></tr></thead><tbody>
<tr><td>Maze Quest 1</td><td>10 Skeleton Pirates, 2 Cthulhu</td><td>150,000 Gold, 10,000 XP, 1 Luck Totem</td></tr>
<tr><td>Maze Quest 2</td><td>25 Skeleton Pirates, 7 Cthulhu</td><td>250,000 Gold, 14,000 XP</td></tr>
<tr><td>Maze Quest 3</td><td>50 Skeleton Pirates, 15 Cthulhu</td><td>400,000 Gold, 23,000 XP</td></tr></tbody></table></div>
<p>Finishing all three is how you get the Heavenly Pickaxe: it unlocks it for purchase. The quests pay <strong>800,000 Gold</strong> in total, which covers a big part of the 2,000,000 price. The Masked Stranger at the Maze entrance also has a daily Pirate Raid quest with the same targets, worth 50,000 Gold, so you can do both at once.</p>"""),
 ("tips","Tips","""<ul><li>Bring your best weapon and use block and parry against Cthulhu. See our <a href="the-forge-combat-guide.html">combat guide</a>.</li><li>Roll for <strong>Goblin</strong> to save 240,000 Gold on the price.</li><li>Compare it with the <a href="the-forge-prismatic-pickaxe.html">Prismatic Pickaxe</a> and the <a href="the-forge-dragon-head-pickaxe.html">Dragon Head Pickaxe</a>.</li></ul>""")],
 faq=[("How do you get the Heavenly Pickaxe in The Forge?","Take the Ferry to the Secret Maze, reach the end, finish all three Maze quests for Zachariel and Zarall, then buy it for 2,000,000 Gold."),
      ("Is the Heavenite Pickaxe the same as the Heavenly Pickaxe?","Yes. Players often call it the Heavenite Pickaxe, but the in-game name is Heavenly Pickaxe. Heavenite is a separate ore."),
      ("How do you unlock the maze in The Forge?","Take the Ferry on the Frostspire Expanse to the Secret Maze entrance. It was added on January 11, 2026.")],
 sources=[F.wiki("Heavenly_Pickaxe","Heavenly Pickaxe"),F.wiki("Maze_Quest_1","Maze Quests 1–3"),F.wiki("Zachariel"),F.wiki("Frostspire_Expanse","Frostspire Expanse"),F.wiki("Heavenite"),F.wiki("Version_History","Version History")],
 howto=("How to get the Heavenly Pickaxe in The Forge",[("Take the Ferry","Ride the Ferry to the Secret Maze entrance.","maze"),("Cross the maze","Make your way to Zachariel and Zarall at the end.","maze"),("Finish 3 quests","Defeat the Skeleton Pirates and Cthulhu for all three Maze quests.","quests"),("Buy the pickaxe","Pay 2,000,000 Gold, or 1,760,000 as a Goblin.","stats")]))
